files.content:
:root {
  --bg: #1b1b2f;
  --card: #282a4a;
  --accent: #5ce1e6;
  --accent-dark: #2fa6ab;
  --text: #f2f4ff;
  --muted: #a9b0d6;
  --border: #3c3f66;
  --focus: #ffd166;
  --radius: 10px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(0deg, rgba(92, 225, 230, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(92, 225, 230, 0.06) 1px, transparent 1px);
  background-size: 24px 24px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 0 0 3px var(--bg), 0 12px 0 0 #101024, 0 18px 30px rgba(0, 0, 0, 0.45);
  padding: 28px 22px 24px;
}

h1 {
  margin: 0 0 22px;
  font-size: 1.5rem;
  line-height: 1.25;
  text-align: center;
  letter-spacing: 0.02em;
  color: var(--accent);
  text-shadow: 2px 2px 0 #101024;
}

.field {
  margin: 0 0 20px;
  border: 0;
  padding: 0;
}

.field label,
.field legend {
  display: block;
  margin-bottom: 8px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--muted);
  padding: 0;
}

.input-wrap {
  display: flex;
  align-items: center;
  background: #1f2140;
  border: 3px solid var(--border);
  border-radius: var(--radius);
  padding: 0 12px;
}

.prefix {
  color: var(--muted);
  font-weight: 700;
  margin-right: 6px;
}

input[type="number"] {
  width: 100%;
  min-height: 48px;
  border: 0;
  background: transparent;
  color: var(--text);
  font-family: var(--font);
  font-size: 1.125rem;
  padding: 8px 0;
  outline: none;
}

.field > input[type="number"] {
  background: #1f2140;
  border: 3px solid var(--border);
  border-radius: var(--radius);
  padding: 8px 12px;
}

.input-wrap:focus-within,
.field > input[type="number"]:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.35);
}

.tip-buttons {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1 1 0;
  min-width: 72px;
  min-height: 48px;
  font-family: var(--font);
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--text);
  background: #1f2140;
  border: 3px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: transform 0.08s ease, background-color 0.15s ease, border-color 0.15s ease;
}

.tip-btn:hover {
  background: #2d3060;
  border-color: var(--accent-dark);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translateY(2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #101024;
  box-shadow: inset 0 -4px 0 var(--accent-dark);
}

.results {
  margin-top: 8px;
  padding: 16px;
  background: #1f2140;
  border: 3px dashed var(--border);
  border-radius: var(--radius);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
  flex-wrap: wrap;
}

.result-row + .result-row {
  border-top: 2px solid var(--border);
  margin-top: 6px;
  padding-top: 12px;
}

.result-label {
  color: var(--muted);
  font-weight: 600;
}

.result-value {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text);
  overflow-wrap: anywhere;
}

.result-row.total .result-value {
  color: var(--accent);
  font-size: 1.5rem;
}

@media (max-width: 380px) {
  .card {
    padding: 22px 16px 20px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .tip-btn {
    min-width: 60px;
  }
}

(function () {
  "use strict";

  var billInput = document.getElementById("bill");
  var peopleInput = document.getElementById("people");
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll(".tip-btn"));
  var tipAmountEl = document.getElementById("tip-amount");
  var totalPerPersonEl = document.getElementById("total-per-person");

  var tipPercent = 15;

  function formatCurrency(value) {
    if (!isFinite(value) || value < 0) value = 0;
    return "$" + value.toFixed(2);
  }

  function parseNumber(input, fallback) {
    var raw = input.value.trim();
    if (raw === "") return fallback;
    var n = parseFloat(raw);
    return isFinite(n) ? n : fallback;
  }

  function calculate() {
    var bill = parseNumber(billInput, 0);
    if (bill < 0) bill = 0;

    var people = Math.floor(parseNumber(peopleInput, 1));
    if (!isFinite(people) || people < 1) people = 1;

    var tip = bill * (tipPercent / 100);
    var totalPerPerson = (bill + tip) / people;

    tipAmountEl.textContent = formatCurrency(tip);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  function selectTip(button) {
    tipPercent = parseInt(button.getAttribute("data-tip"), 10) || 0;
    tipButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", btn === button ? "true" : "false");
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      selectTip(btn);
    });
  });

  billInput.addEventListener("input", calculate);
  peopleInput.addEventListener("input", calculate);

  // Enter/Space on tip buttons is native button behavior; ensure initial state.
  var defaultBtn = tipButtons.filter(function (b) {
    return b.getAttribute("data-tip") === "15";
  })[0];
  if (defaultBtn) {
    selectTip(defaultBtn);
  } else {
    calculate();
  }
})();
